import{_ as u,a0 as a,w as i,s,ao as d,I as o,x as e,a1 as r,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"怎样打开64位 Ubuntu 的32位支持功能 | LCTT x X-CMD","titleTemplate":false,"description":"怎样打开64位 Ubuntu 的32位支持功能 | LCTT (201404) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"怎样打开64位 Ubuntu 的32位支持功能 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"怎样打开64位 Ubuntu 的32位支持功能 | LCTT (201404) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201404/How to enable 32-bit support for 64-bit Ubuntu 13.10 or greater","title":"怎样打开64位 Ubuntu 的32位支持功能","tag":"201404","desc":""},"relativePath":"201404/How to enable 32-bit support for 64-bit Ubuntu 13.10 or greater.md","filePath":"[post].md"}'),b={name:"201404/How to enable 32-bit support for 64-bit Ubuntu 13.10 or greater.md"};function l(m,t,f,T,g,_){const p=a("Link");return i(),s("div",null,[t[11]||(t[11]=d(`<h1 id="怎样打开64位-ubuntu-的32位支持功能" tabindex="-1">怎样打开64位 Ubuntu 的32位支持功能 <a class="header-anchor" href="#怎样打开64位-ubuntu-的32位支持功能" aria-label="Permalink to “怎样打开64位 Ubuntu 的32位支持功能”">​</a></h1><p>大多数使用基于 Ubuntu/Debian 的发行版的人都更倾向于选择64位的系统，对吧？这是因为64位的系统能够充分发挥你的硬件的全部性能， 它使你能够在更紧张的内存资源下使用更复杂的软件，而且是真的快速使用，不必每次做一件小事都要等上许久。现在，32位仅有一个优点，那就是没有太多兼容性上的问题。每次JAVA更新都很让人很困惑，因为大多数用户都不能获得需要的库文件。在过去，很多别的软件和驱动也没有64位版。</p><p>因此，如果现在你有一个64位架构的系统，而且你可以使用之前的支持：包括驱动、64位版本和任何一个你需要的软件。这样就避免了所有的问题，对吧？现在有一个让你可以在64位系统中使用32位软件的方法，爽吗？就在你读了这篇文章然后照着做了之后就可以了。如果你有一个13.10或更高版本的Ubuntu/Debian，你需要安装一个叫做 ia32-libs 的基础包。现在，这个包已经被废弃了，所以你必须手工安装。</p><p>下面的命令可以在 Ubuntu/Debian 13.10 或更高的发行版上运行。</p><p>###第一步: 确认你有一个64位架构的内核</p><p>你可以打开终端然后输入：</p><pre><code>dpkg --print-architecture
</code></pre><p>你将会看到像下面这样的内容:</p><pre><code>amd64
</code></pre><p>这说明着你已经拥有了64位架构内核。</p><p>###第二步: 确认你打开了多架构支持功能</p><p>(多架构支持可以让你在有64位库的情况下使用32位库。)</p><p>输入:</p><pre><code>dpkg --print-foreign-architectures
</code></pre><p>输出是:</p><pre><code>i386
</code></pre><p>如果你还没有多架构支持你需要打开它。</p><p>另一种第二步: 打开多架构支持。</p><p>输入:</p><pre><code>sudo dpkg --add-architecture i386

sudo apt -get update
</code></pre><p>然后就会开始下载更新然后运行。</p><p>之后你需要输入:</p><pre><code>sudo apt-get dist-upgrade
</code></pre><p>它会检查你已经拥有的库文件是否有更新的版本。</p><p>若果然有的话，它会问你是否需要更新(y/n)。</p><p>如此这般，你就已经成功地为你的64位系统安装了32位支持了。</p><hr>`,27)),o("p",null,[t[1]||(t[1]=e("via: ",-1)),r(p,{href:"http://www.unixmen.com/enable-32-bit-support-64-bit-ubuntu-13-10-greater/"},{default:n(()=>[...t[0]||(t[0]=[e("http://www.unixmen.com/enable-32-bit-support-64-bit-ubuntu-13-10-greater/",-1)])]),_:1})]),o("p",null,[t[4]||(t[4]=e("译者：",-1)),r(p,{href:"https://github.com/crowner"},{default:n(()=>[...t[2]||(t[2]=[e("crowner",-1)])]),_:1}),t[5]||(t[5]=e(" 校对：",-1)),r(p,{href:"https://github.com/wxy"},{default:n(()=>[...t[3]||(t[3]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[8]||(t[8]=e("本文由 ",-1)),r(p,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原创翻译，",-1)),r(p,{href:"http://linux.cn/"},{default:n(()=>[...t[7]||(t[7]=[e("Linux中国",-1)])]),_:1}),t[10]||(t[10]=e(" 荣誉推出",-1))])])}const U=u(b,[["render",l]]);export{C as __pageData,U as default};
